import{_ as l,c as a,o as e,ao as o}from"./chunks/framework.DAsozCiY.js";const k=JSON.parse('{"title":"Vilinko Studio 软件服务条款","description":"","frontmatter":{"prev":false},"headers":[],"relativePath":"agreement/tos.md","filePath":"agreement/tos.md"}'),t={name:"agreement/tos.md"};function r(n,i,u,h,d,s){return e(),a("div",null,i[0]||(i[0]=[o('<h1 id="vilinko-studio-软件服务条款" tabindex="-1">Vilinko Studio 软件服务条款 <a class="header-anchor" href="#vilinko-studio-软件服务条款" aria-label="Permalink to &quot;Vilinko Studio 软件服务条款&quot;">​</a></h1><p><a href="/en/agreement/tos.html">【English Version】</a></p><div class="tip custom-block"><p class="custom-block-title">版本</p><p>初版发布日期：2025 年 8 月 6 日</p><p>最近更新日期：2025 年 8 月 6 日</p></div><p>感谢您使用 Vilinko Studio 软件。使用我们的服务即表示您已同意本条款。我们始终在不断更改和改进我们的服务。我们可能会增加或删除功能，也可能暂停或彻底停止某项服务。您可以随时停止使用我们的服务，我们也可以随时对我们的服务增加新的限制。如果不同语言的 Vilinko Studio 软件服务条款出现歧义，以<strong>简体中文版</strong>为准。</p><h2 id="一、协议接受与范围​" tabindex="-1">一、协议接受与范围​ <a class="header-anchor" href="#一、协议接受与范围​" aria-label="Permalink to &quot;一、协议接受与范围​&quot;">​</a></h2><ul><li>本协议是您（用户）与 Vilinko Studio（以下简称 &quot;我们&quot;）之间关于使用 Vilinko Studio 提供的各类互联网信息技术工具及相关服务（以下简称 &quot;服务&quot;）所订立的具有法律效力的协议。​</li><li>服务包括但不限于：用户登录系统、论坛服务、个性化定制功能、电脑桌面美化工具、文件解释器及其他由 Vilinko Studio 开发并提供的软件服务。​</li><li>您在使用 Vilinko Studio 任何服务前，应仔细阅读并理解本协议。一旦您使用或访问 Vilinko Studio 的任何服务，即表示您已接受并同意本协议的全部条款和条件。​</li></ul><h2 id="二、服务说明与使用规范​" tabindex="-1">二、服务说明与使用规范​ <a class="header-anchor" href="#二、服务说明与使用规范​" aria-label="Permalink to &quot;二、服务说明与使用规范​&quot;">​</a></h2><ul><li>2.1 Vilinko Studio 提供的服务可能包含免费服务和付费服务，具体以服务实际提供情况为准。​</li><li>2.2 您应按照服务的既定功能和使用说明合理使用各项服务，不得利用服务进行任何违法违规活动。​</li><li>2.3 您不得对服务进行反向工程、反向编译、反汇编或其他类似行为，除非法律法规另有明确规定。​</li><li>2.4 您不得未经授权使用、复制、传播、修改 Vilinko Studio 提供的任何软件、代码、文本、图像、音频、视频等内容。</li></ul><h2 id="三、用户账号与安全​" tabindex="-1">三、用户账号与安全​ <a class="header-anchor" href="#三、用户账号与安全​" aria-label="Permalink to &quot;三、用户账号与安全​&quot;">​</a></h2><ul><li>3.1 使用部分服务可能需要注册账号，您应提供真实、准确、完整的注册信息，并及时更新。​</li><li>3.2 您应对自己的账号和密码安全负责，不得向任何第三方泄露。因账号被盗用或密码泄露导致的损失，由您自行承担，除非该损失是由于 Vilinko Studio 的故意或重大过失造成。​</li><li>3.3 如发现账号异常使用，您应立即通知我们，并采取必要的安全措施。​</li><li>3.4 您同意，我们有权根据合理怀疑，在必要时暂停或终止涉嫌违规的账号使用。​</li></ul><h2 id="四、知识产权条款​" tabindex="-1">四、知识产权条款​ <a class="header-anchor" href="#四、知识产权条款​" aria-label="Permalink to &quot;四、知识产权条款​&quot;">​</a></h2><ul><li>4.1 Vilinko Studio 拥有其提供的所有软件、服务、网站内容（包括但不限于文字、图像、音频、视频、代码等）的全部知识产权，除非另有明确声明。​</li><li>4.2 部分 Vilinko Studio 软件及相关内容在 GitHub 等平台开源，遵循相应的开源协议（如 MIT、GPL 等）。开源部分的知识产权保护遵循相关开源协议，但本协议中与开源协议不冲突的条款仍然适用。​</li><li>4.3 对于开源部分，您的使用应严格遵守相关开源协议的规定，不得违反开源协议的要求，包括但不限于保留版权声明、不得限制他人使用等。​</li><li>4.4 您在使用服务过程中产生的内容（如论坛帖子、个性化设置等），其知识产权归您所有，但您授予 Vilinko Studio 全球性、非独占、免费、可转授权的使用权，用于提供、展示和改进服务。​</li><li>4.5 未经 Vilinko Studio 书面许可，您不得将服务中包含的任何知识产权用于本协议约定之外的其他目的。​</li><li>4.6 如您认为 Vilinko Studio 的服务侵犯了您的知识产权，请及时联系我们并提供相关证明，我们将依法处理。​</li></ul><h2 id="五、隐私保护​" tabindex="-1">五、隐私保护​ <a class="header-anchor" href="#五、隐私保护​" aria-label="Permalink to &quot;五、隐私保护​&quot;">​</a></h2><ul><li>5.1 我们尊重并保护用户的隐私，收集和使用用户信息将遵循相关法律法规和<a href="./privacy.html">《隐私政策》</a>的规定。​</li><li>5.2 您同意我们按照<a href="./privacy.html">《隐私政策》</a>收集、使用、存储和保护您的个人信息，以提供更优质的服务。​</li><li>5.3 除非法律法规要求或经您明确同意，我们不会向第三方披露您的个人信息。​</li></ul><h2 id="六、免责声明​" tabindex="-1">六、免责声明​ <a class="header-anchor" href="#六、免责声明​" aria-label="Permalink to &quot;六、免责声明​&quot;">​</a></h2><ul><li>6.1 您理解并同意，服务按 &quot;现状&quot; 提供，我们不保证服务无瑕疵、不间断或完全安全。​</li><li>6.2 对于因不可抗力、第三方行为、您的不当使用等原因导致的服务中断或损失，我们不承担责任，除非法律另有规定。​</li><li>6.3 您使用服务所产生的任何风险和后果，由您自行承担。​</li><li>6.4 对于通过服务获取的第三方信息或内容，我们不保证其真实性、准确性和完整性，不对由此产生的任何损失负责。​</li></ul><h2 id="七、服务的变更、中断与终止​" tabindex="-1">七、服务的变更、中断与终止​ <a class="header-anchor" href="#七、服务的变更、中断与终止​" aria-label="Permalink to &quot;七、服务的变更、中断与终止​&quot;">​</a></h2><ul><li>7.1 我们保留随时变更、暂停或终止部分或全部服务的权利，如有重大变更，将尽可能提前通知用户。​</li><li>7.2 如您违反本协议的任何条款，我们有权暂停或终止向您提供服务，且不承担任何责任。​</li><li>7.3 服务终止后，本协议中关于知识产权、免责声明、法律适用等具有持续性的条款仍然有效。​</li></ul><h2 id="八、法律适用与争议解决​" tabindex="-1">八、法律适用与争议解决​ <a class="header-anchor" href="#八、法律适用与争议解决​" aria-label="Permalink to &quot;八、法律适用与争议解决​&quot;">​</a></h2><ul><li>8.1 本协议的订立、效力、解释、履行及争议解决均适用中华人民共和国法律（不包括冲突法规则）。​</li><li>8.2 因本协议引起的或与本协议有关的任何争议，双方应首先通过友好协商解决；协商不成的，任何一方均有权向 Vilinko Studio 所在地有管辖权的人民法院提起诉讼。​</li></ul><h2 id="九、其他条款​" tabindex="-1">九、其他条款​ <a class="header-anchor" href="#九、其他条款​" aria-label="Permalink to &quot;九、其他条款​&quot;">​</a></h2><ul><li>9.1 本协议构成双方关于服务使用的完整协议，替代之前的所有口头或书面约定。​</li><li>9.2 我们有权根据法律法规变化或业务需要修改本协议，修改后的协议将在公布后生效。您继续使用服务即表示接受修改后的协议。​</li><li>9.3 如本协议任何条款被认定为无效或不可执行，不影响其他条款的效力。​</li><li>9.4 本协议中的标题仅为方便阅读，不影响条款的解释。​</li><li>9.5 联系我们：如您对本协议有任何疑问，可通过官方网站提供的联系方式与我们联系。​</li></ul><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><h3 id="第三方政策链接" tabindex="-1">第三方政策链接 <a class="header-anchor" href="#第三方政策链接" aria-label="Permalink to &quot;第三方政策链接&quot;">​</a></h3><ul><li><a href="https://afdian.com/term" target="_blank" rel="noreferrer">爱发电平台服务条款</a></li></ul><h3 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h3><ul><li>创建工单：<a href="https://vilinko-studio.feishu.cn/share/base/form/shrcnMi5t1NY40A0fjdTN2oRO5e" target="_blank" rel="noreferrer">Vilinko Studio 工单创建助手</a></li></ul>',27)]))}const m=l(t,[["render",r]]);export{k as __pageData,m as default};
